import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateShippingOptionTypesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateShippingOptionTypesWorkflow(req.scope)
    .run({
      input: {
        selector: {
          id: "sotype_123"
        },
        update: {
          label: "Standard"
        },
        additional_data: {
          erp_id: "123"
        }
      }
    })

  res.send(result)
}

